/* MWIPLOTSTS : Lot Status Table */
CREATE TABLE MWIPLOTSTS 
(
    /* Lot ID는 모든 Factory에서 Unique */
    LOT_ID                      VARCHAR2(25)     DEFAULT(' ')    NOT NULL,
