    RWK_RET_FLOW                VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    RWK_RET_FLOW_SEQ_NUM        NUMBER(6)        DEFAULT(0)      NOT NULL,  /* Add For V42 */
    RWK_RET_OPER                VARCHAR2(10)     DEFAULT(' ')    NOT NULL,
