    LOT_CMF_20                  VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    /* LOT 이 지워졌을때 SETTING */
    LOT_DEL_FLAG                CHAR(1)          DEFAULT(' ')    NOT NULL,
