    FLOW_IN_TIME                VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    OPER_IN_TIME                VARCHAR2(14)     DEFAULT(' ')    NOT NULL,
    /* Reserve 된 Resource ID */
    RESERVE_RES_ID              VARCHAR2(20)     DEFAULT(' ')    NOT NULL,
    /* Batch Info. */
    BATCH_ID                    VARCHAR2(25)     DEFAULT(' ')    NOT NULL,
