/* MWIPSLTSTS : Sub Lot Status Table */
CREATE TABLE MWIPSLTSTS_OLD 
(
    /* Lot ID는 모든 Factory에서 Unique */
    SUBLOT_ID                   VARCHAR2(30)     DEFAULT(' ')    NOT NULL,
    LOT_ID                      VARCHAR2(25)     DEFAULT(' ')    NOT NULL,
