    SAMPLE_WAIT_FLAG            CHAR(1)          DEFAULT(' ')    NOT NULL,
    /* Sample Result - ' ':Not decision 'Y': Good  'N': No Good */
    SAMPLE_RESULT               CHAR(1)          DEFAULT(' ')    NOT NULL,
