    FROM_TO_FLAG                CHAR(1)          DEFAULT(' ')    NOT NULL,  /* Add For V42 */
    FROM_TO_LOT_ID              VARCHAR2(25)     DEFAULT(' ')    NOT NULL,  /* Mod For V42 */
